export function authCopy(language: string | undefined, key: string): string {
  const lang = (language ?? 'en').split(/[-_]/)[0] as AppLanguage;
  return String(AUTH_FIX_COPY[lang]?.[key] ?? AUTH_COPY[lang]?.[key] ?? AUTH_FIX_COPY.en[key] ?? AUTH_COPY.en[key] ?? key);
}

export function screenCopy(
  language: string | undefined,
  key: string,
  values: Record<string, string | number> = {},
): string {
  const lang = (language ?? 'en').split(/[-_]/)[0] as AppLanguage;
  const value =
    LOCALE_FIX_COPY[lang]?.[key] ??
    PROFILE_COPY[lang]?.[key] ??
    COPY[lang]?.[key] ??
    LOCALE_FIX_COPY.en[key] ??
    PROFILE_COPY.en[key] ??
    COPY.en[key] ??
    key;
  return typeof value === 'function' ? value(values) : value;
}
